  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// USER MODELS\nmodel UserAccount {\n  id        String     @id @default(cuid())\n  username  String     @unique\n  email     String     @unique\n  password  String\n  status    UserStatus @default(ACTIVE)\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  // Relation to UserProfile model\n  userProfileId String? // Foreign key\n  userProfile   UserProfile? @relation(fields: [userProfileId], references: [id])\n\n  // Relation to ServiceListings created by this user (if they are a Cleaner)\n  serviceListings ServiceListing[]\n\n  // Relations for ProfileView\n  profileViews ProfileView[] @relation(\"ViewedProfile\") // Profiles views this user received\n  viewedOthers ProfileView[] @relation(\"ProfileViewer\") // Profiles this user viewed\n\n  // Relations for Shortlist\n  createdShortlists Shortlist[] @relation(\"HomeownerShortlists\") // Shortlists created by this user (if Homeowner)\n  shortlistedIn     Shortlist[] @relation(\"CleanerShortlistedIn\") // Instances where this user (if Cleaner) was shortlisted\n\n  // Relations for ConfirmedMatch\n  confirmedMatchesAsHomeowner ConfirmedMatch[] @relation(\"HomeownerMatches\") // Matches this user (as Homeowner) has confirmed\n  // Cleaners are linked to ConfirmedMatch via their ServiceListings\n\n  // Relations for ServiceBooking\n  serviceBookings ServiceBooking[] @relation(\"HomeownerBookings\") // Past service bookings\n  ServiceBooking  ServiceBooking[]\n}\n\n// Define standard permissions\nenum Permission {\n  MANAGE_SERVICES // e.g., Cleaners creating/managing their listings\n  ADMIN_PRIVILEGES // e.g., UserAdmins managing users, profiles, etc.\n  SEARCH_CLEANERS // e.g., Homeowners searching for cleaners/listings\n  VIEW_REPORTS // e.g., Platform Management viewing reports\n}\n\n// New UserProfile model to allow dynamic creation\nmodel UserProfile {\n  id          String       @id @default(cuid())\n  name        String       @unique // e.g., \"HomeOwner\", \"Cleaner\", \"UserAdmin\"\n  permissions Permission[] // List of permissions granted to this profile\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  // Relation back to UserAccount\n  userAccounts UserAccount[]\n  // Relation to ServiceListing (if a profile can be associated with listings, e.g., category management)\n  // serviceListings ServiceListing[] // Optional: Add if profiles manage listings directly\n\n  status UserProfileStatus @default(ACTIVE) // Status of the user profile\n}\n\nenum UserProfileStatus {\n  ACTIVE\n  SUSPENDED\n}\n\n// Relation from UserAccount to ServiceListing\nmodel ServiceListing {\n  id           String   @id @default(cuid())\n  serviceType  String // e.g., \"Deep Cleaning\", \"Basic Cleaning\", \"Window Cleaning\"\n  title        String\n  description  String\n  ratePerHr    Float // Rate per hour\n  duration     Float? // Duration in hours (optional for existing records)\n  availability String? // Availability schedule (optional for existing records)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Relation to the Cleaner (UserAccount) who created the listing\n  cleanerId String\n  cleaner   UserAccount @relation(fields: [cleanerId], references: [id])\n\n  // Relation to ConfirmedMatches\n  confirmedMatches ConfirmedMatch[]\n\n  status ServiceListingStatus @default(ACTIVE) // Status of the listing\n\n  @@index([cleanerId]) // Index for faster lookups by cleaner\n  @@index([cleanerId, status]) // For cleaners to view their listings by status\n}\n\nenum ServiceListingStatus {\n  ACTIVE\n  SUSPENDED\n  // ARCHIVED // Future potential status\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n  BANNED\n}\n\n// Model to track profile views\nmodel ProfileView {\n  id              String       @id @default(cuid())\n  viewedProfileId String // ID of the UserAccount (Cleaner) whose profile was viewed\n  viewedProfile   UserAccount  @relation(\"ViewedProfile\", fields: [viewedProfileId], references: [id], onDelete: Cascade) // If cleaner account is deleted, views are removed\n  viewerId        String? // ID of the UserAccount who viewed the profile (optional, if logged in)\n  viewer          UserAccount? @relation(\"ProfileViewer\", fields: [viewerId], references: [id], onDelete: SetNull) // If viewer account is deleted, viewerId becomes null\n  viewedAt        DateTime     @default(now())\n\n  @@index([viewedProfileId, viewedAt])\n  @@index([viewerId])\n}\n\n// Model to track when a Homeowner shortlists a Cleaner\nmodel Shortlist {\n  id          String      @id @default(cuid())\n  homeownerId String // ID of the UserAccount (Homeowner) who created the shortlist\n  homeowner   UserAccount @relation(\"HomeownerShortlists\", fields: [homeownerId], references: [id], onDelete: Cascade)\n  cleanerId   String // ID of the UserAccount (Cleaner) who was shortlisted\n  cleaner     UserAccount @relation(\"CleanerShortlistedIn\", fields: [cleanerId], references: [id], onDelete: Cascade)\n  createdAt   DateTime    @default(now())\n\n  @@unique([homeownerId, cleanerId]) // A homeowner can shortlist a cleaner only once\n  @@index([homeownerId])\n  @@index([cleanerId])\n}\n\n// Model to track confirmed matches between a Homeowner and a Cleaner's ServiceListing\nmodel ConfirmedMatch {\n  id               String         @id @default(cuid())\n  serviceListingId String\n  serviceListing   ServiceListing @relation(fields: [serviceListingId], references: [id], onDelete: Cascade) // If listing deleted, match is removed\n  homeownerId      String\n  homeowner        UserAccount    @relation(\"HomeownerMatches\", fields: [homeownerId], references: [id], onDelete: Cascade) // If homeowner deleted, match is removed\n  confirmationDate DateTime       @default(now()) // Date the match was confirmed\n  // status        MatchStatus @default(CONFIRMED) // Optional: For future expansion (e.g., COMPLETED, CANCELLED_BY_HOMEOWNER, CANCELLED_BY_CLEANER)\n\n  @@index([serviceListingId])\n  @@index([homeownerId])\n  @@index([confirmationDate])\n  @@index([serviceListingId, confirmationDate]) // For cleaner's view, filtering by date\n}\n\n// Service Booking model for tracking completed services\nmodel ServiceBooking {\n  id          String        @id @default(cuid())\n  bookingId   String        @unique\n  cleanerId   String\n  cleaner     UserAccount   @relation(fields: [cleanerId], references: [id])\n  homeownerId String\n  homeowner   UserAccount   @relation(\"HomeownerBookings\", fields: [homeownerId], references: [id])\n  serviceDate DateTime\n  status      BookingStatus\n  serviceType String\n  ratePerHr   Float\n  hours       Float\n  totalAmount Float\n  createdAt   DateTime      @default(now())\n\n  @@index([homeownerId])\n  @@index([cleanerId])\n  @@index([serviceDate])\n}\n\nenum BookingStatus {\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n}\n",
